// crc64: CRC-64/XZ of 8 MiB of generated bytes, table-driven. Prints the
// CRC in hexadecimal.

fn main() {
    let table: Vec<u64> = (0..256u64)
        .map(|b| (0..8).fold(b, |c, _| if c & 1 == 1 { c >> 1 ^ 0xC96C5795D7870F42 } else { c >> 1 }))
        .collect();
    let data: Vec<u8> = (0..1i64 << 23).map(|i| ((i * 2654435761) >> 13 & 255) as u8).collect();
    let c = data.iter().fold(!0u64, |c, &b| table[((c ^ b as u64) & 255) as usize] ^ c >> 8);
    println!("{:016x}", !c);
}
